static NSDictionary *Choices(NSString *name){return @{@"name":name,@"applications":@[@"com.burbn.instagram"],@"manualIdentifiers":NSNull.null,@"proxyReference":@""};}
static NSDictionary *Read(NSString *file){NSData *bytes=[NSData dataWithContentsOfFile:file];return bytes?[NSJSONSerialization JSONObjectWithData:bytes options:0 error:nil]:nil;}
static NSDictionary *Refresh(LBXContainerRootMutationCoordinator *value){return Await(^(void (^complete)(NSDictionary *)){[value refreshWithCompletion:complete];});}
static NSDictionary *Create(LBXContainerRootMutationCoordinator *value,NSString *name){return Await(^(void (^complete)(NSDictionary *)){[value beginCreationWithChoices:Choices(name) completion:complete];});}
