static LBXLicenseOwner *Source(LBXLicenseVault *vault){LBXLicenseOwner *value=[[LBXLicenseOwner alloc] initWithVault:vault];[value testUseProtocol:FixtureProtocol.class publicKey:TestLicensePublicDER() keyID:TestLicenseKeyID()];return value;}
