- (void)install {[LBXContainerRootMutationCoordinator testUseLicenseSender:^(NSString *operation,NSString *key,void (^complete)(NSDictionary *)){
    Check([operation isEqual:@"validate"]&&!key,@"coordinator requests fresh fixed validation, no key or Boolean grant");NSDictionary *request=LBXLicenseIPCRequest(operation,key);[self.source handleRequest:request completion:^(NSDictionary *reply){Check(LBXLicenseIPCValidateReply(reply,request,LBXLicenseIPCClock()),@"real signed source owner returns strict license envelope");NSMutableDictionary *call=[@{@"operation":@"license",@"reply":reply,@"complete":[complete copy]} mutableCopy];@synchronized(self){if([self.hold isEqual:@"license"]){[self.held addObject:call];return;}}complete(reply);if(self.duplicate)complete(reply);}];
    } mutationSender:^(NSString *operation,NSDictionary *arguments,void (^complete)(NSDictionary *)){
        NSDictionary *request=LBXContainerMutationIPCRequest(operation,arguments);Check(LBXContainerMutationIPCValidateRequest(request,LBXContainerMutationIPCClock()),@"exact protocol request reaches actual root fixture owner");NSMutableDictionary *call=[@{@"operation":operation,@"arguments":arguments,@"request":request,@"complete":[complete copy]} mutableCopy];@synchronized(self){[self.calls addObject:call];if([self.skip isEqual:operation]){[self.held addObject:call];return;}}
        [self.root handleRequest:request completion:^(NSDictionary *reply){Check(LBXContainerMutationIPCValidateReply(reply,request,LBXContainerMutationIPCClock()),@"actual root store/owner returns strict bounded envelope");NSDictionary *delivered=reply;
            @synchronized(self){call[@"reply"]=reply;if([self.revokeAfter isEqual:operation]){self.revokeAfter=nil;licenseMode=@"revoked";}if([self.unconfirm isEqual:operation])delivered=LBXContainerMutationIPCFailure(request,@"unconfirmed");if([self.malformed isEqual:operation]){NSMutableDictionary *bad=[reply mutableCopy];bad[@"runtimeAccepted"]=@YES;delivered=bad;}if([self.hold isEqual:operation]){[self.held addObject:call];return;}}
            if(self.wrongProxyAcknowledgement&&[operation isEqual:@"stage-create"]&&[reply[@"result"] isEqual:@"staged"]){
                NSMutableDictionary *bad=[reply mutableCopy],*state=[reply[@"state"] mutableCopy],*slot=[state[@"pending"] mutableCopy],*document=[slot[@"configuration"] mutableCopy];
                document[@"proxyReference"]=@"bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb";slot[@"configuration"]=document;state[@"pending"]=slot;bad[@"configuration"]=document;bad[@"state"]=state;delivered=bad;
                Check(!LBXContainerMutationIPCValidateReply(delivered,request,LBXContainerMutationIPCClock()),@"explicit synthetic stage acknowledgement with only reference changed is invalid despite exact correlation");
            }
            complete(delivered);if(self.duplicate)complete(delivered);
        }];
    }];}
- (NSMutableDictionary *)takeHeld {@synchronized(self){NSMutableDictionary *call=self.held.firstObject;if(call)[self.held removeObjectAtIndex:0];return call;}}
- (NSUInteger)count:(NSString *)operation {@synchronized(self){NSUInteger count=0;for(NSDictionary *call in self.calls)if([call[@"operation"] isEqual:operation])count++;return count;}}
- (NSUInteger)heldCount {@synchronized(self){return self.held.count;}}
- (void)restart {
    LBXLicenseVault *vault=[LBXLicenseVault openExistingDirectory:[self.base stringByAppendingPathComponent:@"vault"] error:nil];
    Check(vault!=nil,@"source service restart opens verified established vault without creating or repairing");
    [vault testUsePublicKey:TestLicensePublicDER() keyID:TestLicenseKeyID()];self.vault=vault;self.source=Source(vault);
    self.store=[LBXContainerConfigurationStore openDirectory:self.storePath licenseOwner:self.source create:NO error:nil];
    Check(self.store!=nil,@"source service restart opens established pinned configuration namespace");
    self.root=[[LBXContainerRootMutationOwner alloc] initWithLicenseOwner:self.source configurationStore:self.store pendingDirectory:self.pendingPath];
    Check(self.root!=nil,@"source service restart assembles no pending bootstrap or replay grant");[self install];
}
