    Check([record[@"applications"] isEqual:@[@"com.burbn.instagram",@"com.facebook.Facebook",@"com.atebits.Tweetie2"]],@"manual setup persists canonical all-three membership without runtime acceptance claims");
    LBXContainerConfiguration *expected=[LBXContainerConfiguration fromDictionary:record error:nil];
    NSDictionary *nextIDs=[LBXContainerConfiguration createWithName:@"second syntactic fixture" applications:@[@"com.burbn.instagram"] manualIdentifiers:nil proxyReference:@"" error:nil].privateDictionary[@"identifiers"];
    NSMutableDictionary *nextFields=[nextIDs mutableCopy];NSMutableString *name=[@"Manual retained update" mutableCopy];manual.unconfirm=@"stage-update";
    NSDictionary *unknown=Await(^(void (^complete)(NSDictionary *)){
