        [name appendString:@" caller mutation"];nextFields[@"serialNumber"]=@"invalid";
    });NSDictionary *intent=[c pendingMutation:nil],*slot=Read(manual.statePath)[@"pending"][@"slot"];
    Check(Is(unknown,@"unconfirmed")&&[intent[@"configuration"][ @"identifiers"] isEqual:nextIDs]&&[intent[@"expected"] isEqual:record]&&[slot[@"configuration"][@"name"] isEqual:@"Manual retained update"],@"unconfirmed manual update preserves exact full candidate and expected, independent of mutable inputs");
    NSUInteger stages=[manual count:@"stage-update"];manual.unconfirm=nil;
