    Service *legacy=NewService(base,@"legacy");LBXContainerRootMutationCoordinator *old=[LBXContainerRootMutationCoordinator coordinator];NSDictionary *oldSaved=Create(old,@"Readable legacy snapshot");record=oldSaved[@"configuration"];
    NSData *flat=[NSJSONSerialization dataWithJSONObject:record options:NSJSONWritingSortedKeys|NSJSONWritingWithoutEscapingSlashes error:nil];
    Check([flat writeToFile:Record(legacy,record) options:NSDataWritingAtomic error:nil]&&!chmod(Record(legacy,record).fileSystemRepresentation,0600),@"physical legacy UNKNOWN reservation fixture is exact flat record, not an editable envelope");
    expected=[LBXContainerConfiguration fromDictionary:record error:nil];NSData *pendingBytes=[NSData dataWithContentsOfFile:legacy.statePath];
    NSDictionary *denied=Await(^(void (^complete)(NSDictionary *)){[old beginUpdateOfConfiguration:expected name:@"Legacy cannot thaw" applications:nil manualIdentifiers:nil completion:complete];});
    Check(Is(denied,@"conflict")&&[[NSData dataWithContentsOfFile:Record(legacy,record)] isEqual:flat]&&[[NSData dataWithContentsOfFile:legacy.statePath] isEqual:pendingBytes],@"legacy UNKNOWN refusal preserves record and root empty epoch without silently thawing or occupying pending");
